package com.catpuzzle.assistant; import android.graphics.*;import java.util.*; public final class BoardAnalyzer{public static final class Board{public int n,left,top,size;public int[][] region;public boolean[][] cat,blocked;public float confidence;public String note;public float cx(int c){return left+(c+.5f)*size/n;}public float cy(int r){return top+(r+.5f)*size/n;}} static int dist(int a,int b){int x=Color.red(a)-Color.red(b),y=Color.green(a)-Color.green(b),z=Color.blue(a)-Color.blue(b);return x*x+y*y+z*z;}static float sat(int c){int x=Math.max(Color.red(c),Math.max(Color.green(c),Color.blue(c))),n=Math.min(Color.red(c),Math.min(Color.green(c),Color.blue(c)));return x==0?0:(x-n)/(float)x;}static int avg(Bitmap b,int x0,int y0,int x1,int y1){long r=0,g=0,bl=0,n=0;int sx=Math.max(1,(x1-x0)/6),sy=Math.max(1,(y1-y0)/6);for(int y=y0;y<y1;y+=sy)for(int x=x0;x<x1;x+=sx){int c=b.getPixel(Math.max(0,Math.min(b.getWidth()-1,x)),Math.max(0,Math.min(b.getHeight()-1,y)));r+=Color.red(c);g+=Color.green(c);bl+=Color.blue(c);n++;}return Color.rgb((int)(r/n),(int)(g/n),(int)(bl/n));} public static Board analyze(Bitmap b){if(b==null)return null;int w=b.getWidth(),h=b.getHeight(),bestN=0,L=0,T=0,S=0;double best=-1;for(int n=6;n<=12;n++)for(float f:new float[]{.78f,.82f,.86f,.90f,.94f}){int s=(int)(w*f),l=(w-s)/2;for(float tf:new float[]{.23f,.26f,.29f,.32f,.35f,.38f,.41f}){int t=(int)(h*tf);if(t+s>=h*.94f)continue;double sc=score(b,l,t,s,n);if(sc>best){best=sc;bestN=n;L=l;T=t;S=s;}}}if(bestN==0)return null;Board q=new Board();q.n=bestN;q.left=L;q.top=T;q.size=S;q.region=new int[q.n][q.n];q.cat=new boolean[q.n][q.n];q.blocked=new boolean[q.n][q.n];ArrayList<Integer> pal=new ArrayList<>();int cs=S/q.n;for(int r=0;r<q.n;r++)for(int c=0;c<q.n;c++){int x=L+c*cs,y=T+r*cs,base=avg(b,x+cs/4,y+cs/4,x+3*cs/4,y+3*cs/4),idx=-1,bd=Integer.MAX_VALUE;for(int i=0;i<pal.size();i++){int dd=dist(base,pal.get(i));if(dd<bd){bd=dd;idx=i;}}if(idx<0||bd>4332){pal.add(base);idx=pal.size()-1;}q.region[r][c]=idx;int bright=0,dark=0,total=0;for(int yy=1;yy<9;yy++)for(int xx=1;xx<9;xx++){int co=b.getPixel(x+xx*cs/10,y+yy*cs/10),br=(Color.red(co)+Color.green(co)+Color.blue(co))/3;if(br>225&&(Math.abs(xx-yy)<=1||Math.abs((10-xx)-yy)<=1))bright++;if(br<65)dark++;total++;}q.cat[r][c]=dark>Math.max(6,total/8);q.blocked[r][c]=!q.cat[r][c]&&bright>=6;}HashSet<Integer> regs=new HashSet<>();for(int[] row:q.region)for(int v:row)regs.add(v);float fit=1f-Math.min(1f,Math.abs(regs.size()-q.n)/(float)q.n);q.confidence=(float)Math.max(0,Math.min(1,.45+best*.35+fit*.2));q.note=q.n+"×"+q.n+", цветов "+regs.size()+", "+Math.round(q.confidence*100)+"%";return q;}static double score(Bitmap b,int l,int t,int s,int n){int cs=s/n,k=0;double col=0,ed=0;for(int r=0;r<n;r++)for(int c=0;c<n;c++){int x=l+c*cs,y=t+r*cs,a=avg(b,x+cs/4,y+cs/4,x+3*cs/4,y+3*cs/4);col+=Math.max(.05,sat(a));if(c<n-1)ed+=Math.min(1,dist(a,avg(b,x+cs+2,y+cs/3,x+cs+cs/4,y+2*cs/3))/14000.);if(r<n-1)ed+=Math.min(1,dist(a,avg(b,x+cs/3,y+cs+2,x+2*cs/3,y+cs+cs/4))/14000.);k++;}return col/k*.45+ed/Math.max(1,2*n*(n-1))*.55;}}